# Rebuild exact local Wizard's Tower V1 with Python stdlib only.
import base64,gzip,hashlib,runpy
from pathlib import Path
here=Path(__file__).resolve().parent
source=gzip.decompress(base64.b64decode("""""",validate=True))
assert hashlib.sha256(source).hexdigest()=="486dcbcbcc658737e83901f6a6002980d5b07749fb03a1ca2a3cab9a65da1fb6"
script=here/"build_tower.py"
if script.exists() and script.read_bytes()!=source: raise RuntimeError("Preserve manually edited source before replay")
script.write_bytes(source)
runpy.run_path(str(script),run_name="__main__")
assert hashlib.sha256(gzip.decompress((here/"prefab-extension/wizards_tower.nbt").read_bytes())).hexdigest()=="d09aa4d84a38210a25f7e89311e221587a0eb629456932e45c9a7c630d066e2d"
